def install(app, accounts, root, client_request):
    router = APIRouter(prefix="/v1/identity")
    cipher = Access(root / "identity/peers").cipher

    def active(source, actor):
        profile = accounts.account(actor.user_id)
        if actor.platform_role != profile["role"] or not accounts.has_grant(actor.user_id, source):
            raise CoreError("应用账号授权已失效", "forbidden")
        if actor.auth_kind == "session":
            with accounts.connection() as db:
                found = db.execute(
                    "SELECT 1 FROM account_session WHERE digest=? AND account_id=? AND audience=? AND expires>?",
                    (actor.session_id, actor.user_id, source, int(time.time())),
                ).fetchone()
            if not found:
                raise CoreError("应用会话已失效", "unauthorized")
        elif actor.api_key_id != "dsh-plugin-v1":
            raise CoreError("需要受限应用身份", "forbidden")

class Runtime:
    def __init__(self, root, host, notify):
        root = Path(root)
        root.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.lock = (root / "worker.lock").open("a")
        try:
            fcntl.flock(self.lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            self.lock.close()
            raise CoreError("此配置已有执行进程", "profile_busy") from None
        self.store = Store(root)
        from .retired_providers import retire_providers

        try:
            retire_providers(self.store)
        except BaseException:
            self.store.db.close()
            self.lock.close()

export class RuntimeManager {
  readonly root: string;
  private entries = new Map<string, Entry>();
  private closed = false;
  constructor(root = process.env.DSH_FPL_RUNTIME_ROOT || join(homedir(), "Library/Application Support/DSH-FPL-Runtime/.runtime")) {
    this.root = formalDirectory(root);
  }
  register(options: ManagedServiceOptions) {
    if (this.closed) throw new SetupError("setup_disposed", "安装控制已关闭");
    if (!/^(core|dsh-[a-z][a-z0-9-]{0,79})$/.test(options.id)) throw new SetupError("service_id", "服务标识无效");
    if (this.entries.has(options.id)) throw new SetupError("service_conflict", "此服务已有安装控制");
    const handle = new ManagedService(this, options.id);
    this.entries.set(options.id, { options: { ...options }, handle, name: options.id, step: "等待检查" });
    return handle;
  }
  private entry(id: string) {
    const value = this.entries.get(id);
    if (!value) throw new SetupError("service_unregistered", "请先启用对应的工坊插件");

export async function prepareUv(root: string, signal: AbortSignal): Promise<string> {
  try {
    const { stdout } = await runProgram("uv", ["--version"], root, signal);
    if (/^uv 0\.12\.18(?:\s|$)/.test(stdout.trim())) return "uv";
  } catch (error: any) {
    signal.throwIfAborted();
    if (error.code !== "ENOENT") throw new SetupError("uv_unusable", "现有 uv 无法执行，请检查路径或重试");
  }
  const asset = process.platform === "darwin" && uvAssets[process.arch];
  if (!asset) throw new SetupError("unsupported_platform", "托管安装首轮仅支持 macOS");
  const directory = join(root, "tools", "uv-0.12.18-" + process.arch), program = join(directory, "uv");
  const release = await installationLock(root, "uv");
