export function registerNativeTools(ctx: Context, specs: readonly NativeToolSpec[],
  request: (operation: { method: string; path: string }, args: any, execution: WorkshopExecutionContext) => Promise<any>) {
  const names = new Set<string>();
  for (const spec of specs) {
    if (!/^fpl_[a-z0-9_]{1,68}$/.test(spec.name) || names.has(spec.name)) throw new Error("工坊工具名无效或重复");
    names.add(spec.name);
  }
  const fiber = ctx.inject(["tools"], (scope: any) => {
    const Ajv = (AjvModule as any).default || AjvModule;
    const ajv = new Ajv({ strict: false, allErrors: true, validateFormats: false });
    for (const spec of specs) {
      const validate = ajv.compile(spec.inputSchema);
      const validateOutput = spec.outputSchema && ajv.compile(spec.outputSchema);
      scope.effect(() => scope.tools.register({
        name: spec.name, description: spec.description, parameters: hostSchema(spec.inputSchema),
        output: { schema: hostSchema(spec.outputSchema || {}), render: (_args: any, value: any) => [{ type: "text", text: JSON.stringify(value) }],
          presentationMeta: (_args: any, value: any) => ({ title: spec.title, status: value?.status || null,
            task_id: value?.task_id || value?.id || null, resource_id: value?.resource?.id || null }) },

def install(app, accounts, root, client_request):
    router = APIRouter(prefix="/v1/identity")
    cipher = Access(root / "identity/peers").cipher

    def active(source, actor):
        profile = accounts.account(actor.user_id)
        if actor.platform_role != profile["role"] or not accounts.has_grant(actor.user_id, source):
            raise CoreError("应用账号授权已失效", "forbidden")
        if actor.auth_kind == "session":
            with accounts.connection() as db:
                found = db.execute(
                    "SELECT 1 FROM account_session WHERE digest=? AND account_id=? AND audience=? AND expires>?",
                    (actor.session_id, actor.user_id, source, int(time.time())),
                ).fetchone()
            if not found:
                raise CoreError("应用会话已失效", "unauthorized")
        elif actor.api_key_id != "dsh-plugin-v1":
            raise CoreError("需要受限应用身份", "forbidden")

class Runtime:
    def __init__(self, root, host, notify):
        root = Path(root)
        root.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.lock = (root / "worker.lock").open("a")
        try:
            fcntl.flock(self.lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            self.lock.close()
            raise CoreError("此配置已有执行进程", "profile_busy") from None
        self.store = Store(root)
        from .retired_providers import retire_providers

        try:
            retire_providers(self.store)
        except BaseException:
            self.store.db.close()
            self.lock.close()

