export async function applicationRequest(ctx, config, endpoint, applicationId, operation, arguments_, context) {
  const managed = !config.credentialFile && await ctx.dshCore.localServiceConfiguration?.("dsh-" + applicationId);
  let credentialFile;
  try {
    credentialFile = managed?.credentialFile || await credentialLocation(config.credentialFile, "dsh-" + applicationId, config.serviceDirectory);
    const stat = await lstat(credentialFile);
    if (!stat.isFile() || stat.isSymbolicLink() || stat.mode & 0o077)
      throw new Error("应用凭据文件必须仅所有者可读。");
  } catch (error) {
    if (error.code === "ENOENT" || error.code === "FPL_SETUP_REQUIRED") throw failure("FPL_SETUP_REQUIRED", "请先在 FPL 安装与连接设置中安装并授权此工坊。");
    throw error;
  }
  const options = JSON.parse(await readFile(credentialFile, "utf8"));
  if (options.endpoint !== endpoint.origin || typeof options.token !== "string") throw new Error("应用凭据与服务地址不匹配。");
  const path = operation.path.replace(/\{([^}]+)\}/g, (_match, key) => {
    const value = arguments_.path?.[key];
    if (typeof value !== "string" || !value) throw failure("FPL_INVALID_ARGS", "缺少路径参数：" + key);
    return encodeURIComponent(value);

